 else{var supportRequest=r.Kind=="Team"&&r.Channel=="InApp"&&r.UnitId!=null&&await new CommunityService(db,a).Mine(tenant).AnyAsync(m=>m.ChapterId==r.UnitId);if(!supportRequest)await a.Require(tenant,r.Kind=="Group"?"communications.groups":"communications.inbox",r.UnitId);if(supportRequest&&((r.MemberIds??[]).Length>0||(r.AdminIds??[]).Length>0))throw new AccessDeniedException();if(r.UnitId!=null&&!await db.Units.AnyAsync(u=>u.TenantId==tenant&&u.Id==r.UnitId&&u.Status=="Active"))throw new AccessDeniedException();var ids=(r.MemberIds??[]).Distinct().ToArray();if(ids.Length>1000)throw new DomainException("Add up to 1000 group members per request");var allowed=(await ms.Directory(tenant));if(r.UnitId!=null){var units=a.InWorkspace(db.Units.Where(u=>u.TenantId==tenant),tenant,r.UnitId).Select(u=>u.Id);allowed=allowed.Where(m=>units.Contains(m.ChapterId));}var members=await (from m in allowed where ids.Contains(m.Id)&&m.Status=="Active" join p in db.Persons on m.PersonId equals p.Id select new{m.Id,p.UserId}).ToListAsync();if(members.Count!=ids.Length)throw new AccessDeniedException();if(r.CommitteeId!=null){var committee=await db.Committees.SingleOrDefaultAsync(cm=>cm.Id==r.CommitteeId&&cm.TenantId==tenant&&cm.Status=="Active")??throw new AccessDeniedException();if(committee.UnitId!=r.UnitId)throw new AccessDeniedException();var roster=db.CommitteeMemberships.Where(cm=>cm.CommitteeId==committee.Id&&cm.StartsAt<=DateTimeOffset.UtcNow&&(cm.EndsAt==null||cm.EndsAt>DateTimeOffset.UtcNow)).Select(cm=>cm.MembershipId);if(await roster.CountAsync(id=>ids.Contains(id))!=ids.Length)throw new AccessDeniedException();}foreach(var member in members.Where(m=>m.UserId!=null).DistinctBy(m=>m.UserId))participants.Add(new(){TenantId=tenant,ConversationId=c.Id,UserId=member.UserId!.Value,MembershipId=member.Id,Role=(r.AdminIds??[]).Contains(member.Id)?"Admin":"Member"});if(!participants.Any(p=>p.UserId==a.UserId))participants.Add(new(){TenantId=tenant,ConversationId=c.Id,UserId=a.UserId,